}

a = 6;
if (a == b) {
    console.log("a and b are equal");  // This will not print anything
}

let c = 5;
c = c + 1;
if (c == 6) {
    console.log("c is equal to 6");  // This will print "c is equal to 6"
}
```

Again, `=` is used for assignment (lines 1, 4, and 7), and `==` is used for comparison (line 6).

